import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { exactResponseFieldsSchema, type ExactResponseFields } from "./exact-response-fields.js";

export type OpensearchConfiguration = {
  /** The endpoint of the Amazon OpenSearch Service domain. */
  domainEndpoint: string;
  /** The name of the Amazon OpenSearch Service index. */
  indexName: string;
  /**
   * Specifies whether to return an exact response or to return an answer generated by the model
   * using the fields you specify from the database.
   */
  exactResponse?: boolean;
  exactResponseFields?: ExactResponseFields;
  /**
   * Contains a list of fields from the Amazon OpenSearch Service that the model can use to generate
   * the answer to the query.
   */
  includeFields?: string[];
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const opensearchConfigurationSchema: Schema<OpensearchConfiguration> =
  s.object<OpensearchConfiguration>(
    {
      domainEndpoint: s.string(),
      indexName: s.string(),
      exactResponse: s.optional(s.boolean()),
      exactResponseFields: s.optional(s.lazy(() => exactResponseFieldsSchema)),
      includeFields: s.optional(s.array(s.string())),
    },
    { additionalProperties: s.json() },
  );
